      running: false,
      intervalSec: 30,
      startedAt: (/* @__PURE__ */ new Date()).toISOString(),
      lastCheck: null,
      checksTotal: 0,
      checksOk: 0,
      successRate: null,
      activeIncident: null,
      checking: false,
      incidents: []
